-- #5387 /roadmap v2 (24/9): kun fremtid. FORSLAG i database/proposals/ (auto-applies IKKE).
-- Ejer-gated: koeres paa ejerens "koer" efter godkendelse af teksterne (billede 24/9 kl. 16, 42 punkter).
-- Idempotent: alle UPDATEs er vagtet (id + status + gammel/ny titel), INSERTs har faste id'er
-- + "where not exists" paa title_en + "on conflict (id) do nothing". Roerer ALDRIG roadmap_votes. Intet DELETE.
-- Baseline 24/9 kl. 16: 23 active, 6 shipped, 0 archived, 809 stemmer.
-- Forventet efter: 42 active, 12 shipped, 6 archived, stemmetal uaendret.
-- PRE-/POST-CHECK: select status, count(*) from roadmap_items group by status order by status;
--                  select count(*) from roadmap_votes;
begin;

-- 1) Eksisterende punkter der lever videre med ny titel og ny raekkefoelge (stemmer bevares)
update roadmap_items r
set sort_order = v.sort_order, title_en = v.new_en, title_da = v.new_da, updated_at = now()
from (values
  ('00000954-0000-4000-8000-000000000011'::text, 10::int, 'Deeper negotiation between managers.'::text, 'Deeper negotiation between managers: counter-offers, riders plus cash, and a deadline.'::text, 'Dybere forhandling mellem managers: modbud, rytter plus penge, og en tidsfrist.'::text),
  ('00000954-0000-4000-8000-000000000012'::text, 20::int, 'A market that tells stories: rumors, rivalries and big moves the whole world talks about.'::text, 'Rumours on the transfer market: hear who is looking, and who else wants the rider you want.'::text, 'Rygter på transfermarkedet: hør hvem der kigger, og hvem der ellers vil have den rytter, du vil have.'::text),
  ('00000954-0000-4000-8000-000000000013'::text, 70::int, 'A smarter season planner: overlapping races, fatigue and qualification rules you can plan a whole season around.'::text, 'A season planner that warns you: fatigue two weeks ahead, and which races a rider can still qualify for.'::text, 'En sæsonplanlægger der advarer dig: trætheden to uger frem, og hvilke løb en rytter stadig kan kvalificere sig til.'::text),
  ('00000954-0000-4000-8000-000000000014'::text, 50::int, 'National championships and national teams: ride for your country, win the jersey.'::text, 'National championships: one day a season your riders race for their country''s jersey.'::text, 'Nationale mesterskaber: én dag om sæsonen kører dine ryttere om deres lands trøje.'::text),
  ('00000954-0000-4000-8000-000000000015'::text, 40::int, 'Coaches as a real resource: balance training load and risk burnout if you push too hard.'::text, 'Staff you can feel: more roles and attributes, and a coach or doctor who changes how your season goes.'::text, 'Personale du kan mærke: flere roller og egenskaber, og en træner eller læge, der ændrer hvordan din sæson går.'::text),
  ('00000954-0000-4000-8000-000000000018'::text, 90::int, 'Earn renown: wins, records and history that build your club''s reputation in the world.'::text, 'Statistics and history: look back at your league and your division, season after season.'::text, 'Statistik og historie: se tilbage på din liga og din division, sæson efter sæson.'::text),
  ('00000954-0000-4000-8000-000000000019'::text, 60::int, 'Road captains and mentors: riders who lift the team around them.'::text, 'Road captains and mentors: you pick the veteran who helps a young rider grow.'::text, 'Vejkaptajner og mentorer: du vælger den veteran, der hjælper en ung rytter på vej.'::text),
  ('00000954-0000-4000-8000-000000000021'::text, 100::int, 'A club museum: champions, legendary riders and the races people still talk about.'::text, 'A club museum: your winners, your legends and the races your club is remembered for.'::text, 'Et klubmuseum: dine vindere, dine legender og de løb, din klub huskes for.'::text),
  ('00000954-0000-4000-8000-000000000022'::text, 110::int, 'Friends and following: follow managers and riders across the world.'::text, 'Friends and following: follow a manager or a rider, invite a friend, and see a world feed of results and trades.'::text, 'Venner og følgere: følg en manager eller en rytter, inviter en ven, og se et verdensfeed med resultater og handler.'::text),
  ('00000954-0000-4000-8000-000000000008'::text, 30::int, 'Young riders you discovered, developed and made your stars.'::text, 'Your own young stars: choose a country you want more young riders from, and steer which rider types your academy produces.'::text, 'Dine egne unge stjerner: vælg et land, du vil have flere unge ryttere fra, og styr hvilke ryttertyper dit akademi får frem.'::text),
  ('df446f41-2314-4c7e-9ed8-38e9538c4798'::text, 70::int, 'Default training programs, and a workshop to share your own.'::text, 'Ready-made training programs, and later a place to share your own.'::text, 'Færdige træningsprogrammer, og senere et sted at dele dine egne.'::text),
  ('cae1e719-1277-4547-b09e-7be6cf4ee514'::text, 60::int, 'Negotiate your board''s goals upward, for a bigger reward.'::text, 'Negotiate your board''s goals upward, for a bigger reward.'::text, 'Forhandl bestyrelsens mål opad, for en større belønning.'::text),
  ('5bb11a13-a5de-402b-94df-f931ca980fca'::text, 90::int, 'Realistic race routes modeled on real racing.'::text, 'Routes that look like real racing: cobbles, a real summit finish, a long valley before the last climb. You can see it on the stage profile.'::text, 'Ruter der ligner rigtig cykling: brosten, en rigtig bjergankomst, en lang dal før den sidste stigning. Du kan se det på etapeprofilen.'::text),
  ('9a14a23b-475e-4870-af03-57e1cab2228d'::text, 80::int, 'The racing math explained in plain words, without revealing exact numbers.'::text, 'Why a stage went the way it did: what climbing, sprint and form did today, in plain words and without the exact numbers.'::text, 'Hvorfor etapen gik, som den gik: hvad klatring, spurt og form gjorde i dag, i klart sprog og uden de præcise tal.'::text)
) as v(id, sort_order, old_en, new_en, new_da)
where r.id = v.id::uuid and r.status = 'active' and r.title_en in (v.old_en, v.new_en);

-- 2) Live nu -> shipped (vises under Already built)
update roadmap_items set status = 'shipped', shipped_at = coalesce(shipped_at, '2026-09-23T00:00:00Z'::timestamptz), title_en = 'The training score for everyone: see how good each training day was for each rider.', title_da = 'Træningsscoren for alle: se hvor god hver træningsdag var for hver rytter.', updated_at = now()
where id = '00000954-0000-4000-8000-000000000005'::uuid and status = 'active' and title_en in ('Long-term development you can see and steer, season over season.', 'The training score for everyone: see how good each training day was for each rider.');
update roadmap_items set status = 'shipped', shipped_at = coalesce(shipped_at, '2026-09-21T00:00:00Z'::timestamptz), title_en = 'Graduation Day: once a season you decide who moves up, who is sold and who leaves.', title_da = 'Graduation Day: én gang pr. sæson bestemmer du, hvem der rykker op, hvem der sælges, og hvem der forlader klubben.', updated_at = now()
where id = '00000954-0000-4000-8000-000000000009'::uuid and status = 'active' and title_en in ('Generational renewal, so your club has a future beyond its current squad.', 'Graduation Day: once a season you decide who moves up, who is sold and who leaves.');
update roadmap_items set status = 'shipped', shipped_at = coalesce(shipped_at, '2026-09-08T00:00:00Z'::timestamptz), updated_at = now()
where id = '96553692-9138-42b1-ba16-8bd7b8247cad'::uuid and status = 'active' and title_en in ('Direct messages and mentions between managers.');

-- 3) Lander 27-28/9 eller er ikke en feature -> archived (stemmerne bliver liggende; flippes til shipped paa flip-dagen)
update roadmap_items set status = 'archived', updated_at = now() where id = '00000954-0000-4000-8000-000000000004'::uuid and status = 'active'; -- lander 28/9: traening pr. loebsdag + ny traeningsside (flip til shipped paa flip-dagen)
update roadmap_items set status = 'archived', updated_at = now() where id = '00000954-0000-4000-8000-000000000006'::uuid and status = 'active'; -- designprincip, ikke en feature
update roadmap_items set status = 'archived', updated_at = now() where id = '00000954-0000-4000-8000-000000000016'::uuid and status = 'active'; -- lander 28/9: U23/junior som rigtige trupper (flip til shipped paa flip-dagen)
update roadmap_items set status = 'archived', updated_at = now() where id = '00000954-0000-4000-8000-000000000017'::uuid and status = 'active'; -- lander 27/9: vaerdiskiftet (flip til shipped paa koerselsdagen)
update roadmap_items set status = 'archived', updated_at = now() where id = 'aa3283fe-59c4-4774-a34b-ee9560efa858'::uuid and status = 'active'; -- samlet i 'Friends and following'
update roadmap_items set status = 'archived', updated_at = now() where id = '2f84b3a4-51ad-4b6d-b056-12008f52bf54'::uuid and status = 'active'; -- samlet i 'Friends and following'

-- 4) Nye punkter til afstemning (28) + 3 allerede live (shipped)
insert into roadmap_items (id, engine, sort_order, status, shipped_at, title_en, title_da, approved, created_at, updated_at)
select v.id::uuid, v.engine, v.sort_order, v.status, v.shipped_at::timestamptz, v.title_en, v.title_da, true, now(), now()
from (values
  ('00005387-0000-4000-8000-000000000201'::text, 'races'::text, 10::int, 'active'::text, null::text, 'Secondary rider type explained: see what a rider''s second type means and where it helps him.'::text, 'Sekundær ryttertype forklaret: se hvad en rytters anden type betyder, og hvor den hjælper ham.'::text),
  ('00005387-0000-4000-8000-000000000202'::text, 'races'::text, 20::int, 'active'::text, null::text, 'Ride for the mountain or points jersey from day one: set the jersey as a rider''s goal, and his race plan follows it.'::text, 'Kør efter bjerg- eller pointtrøjen fra dag ét: sæt trøjen som rytterens mål, og hans løbsplan følger det.'::text),
  ('00005387-0000-4000-8000-000000000203'::text, 'races'::text, 30::int, 'active'::text, null::text, 'Pick where in a stage race a rider peaks, with a main goal and a backup goal.'::text, 'Vælg hvor i et etapeløb en rytter topper, med et hovedmål og et reservemål.'::text),
  ('00005387-0000-4000-8000-000000000204'::text, 'races'::text, 40::int, 'active'::text, null::text, 'The team meeting: your sports director''s plan for each stage, written in cycling terms. No sliders.'::text, 'Holdmødet: din sportsdirektørs plan for hver etape, skrevet i cykelsprog. Ingen skydere.'::text),
  ('00005387-0000-4000-8000-000000000205'::text, 'races'::text, 60::int, 'active'::text, null::text, 'Worlds and Europeans with national teams, and you can be picked as national coach.'::text, 'VM og EM med landshold, og du kan blive udtaget som landstræner.'::text),
  ('00005387-0000-4000-8000-000000000206'::text, 'races'::text, 100::int, 'active'::text, null::text, 'Your calendar colour-coded by your own status: entered, withdrawn, squad set.'::text, 'Din kalender farvet efter din egen status: tilmeldt, afmeldt, hold sat.'::text),
  ('00005387-0000-4000-8000-000000000207'::text, 'races'::text, 110::int, 'active'::text, null::text, 'Watch a stage as a 3D replay with your own riders and colours.'::text, 'Se en etape som 3D-gengivelse med dine egne ryttere og farver.'::text),
  ('00005387-0000-4000-8000-000000000208'::text, 'training'::text, 10::int, 'active'::text, null::text, 'A race sharpener: a short session the day before a race that gives form, not abilities.'::text, 'Åbnere: et kort pas dagen før et løb, der giver form, ikke evner.'::text),
  ('00005387-0000-4000-8000-000000000209'::text, 'training'::text, 20::int, 'active'::text, null::text, 'Plan a whole week per rider in one go: a session for every race day, for one rider or the whole squad.'::text, 'Planlæg en hel uge pr. rytter på én gang: et pas for hver løbsdag, for én rytter eller hele truppen.'::text),
  ('00005387-0000-4000-8000-000000000210'::text, 'training'::text, 30::int, 'active'::text, null::text, 'Form training for riders who are done developing, so a 32-year-old still has something to train for.'::text, 'Formtræning til ryttere, der er færdigudviklede, så en 32-årig stadig har noget at træne for.'::text),
  ('00005387-0000-4000-8000-000000000211'::text, 'training'::text, 40::int, 'active'::text, null::text, 'A training camp: pay to focus one ability hard for a while, and lose race days while you do it.'::text, 'En træningslejr: betal for at fokusere hårdt på én evne i en periode, og mist løbsdage imens.'::text),
  ('00005387-0000-4000-8000-000000000212'::text, 'training'::text, 50::int, 'active'::text, null::text, 'See how many percent a session moved an ability, not just the progress bar.'::text, 'Se hvor mange procent et pas flyttede en evne, ikke kun fremdriftsbjælken.'::text),
  ('00005387-0000-4000-8000-000000000213'::text, 'training'::text, 60::int, 'active'::text, null::text, 'Auto-rest: set your own fatigue limit, and a tired rider rests by himself and goes back to his plan the next day.'::text, 'Auto-hvile: sæt din egen træthedsgrænse, og en træt rytter hviler selv og går tilbage til sin plan dagen efter.'::text),
  ('00005387-0000-4000-8000-000000000214'::text, 'training'::text, 80::int, 'active'::text, null::text, 'Your own labels on riders, so you can find them on the training page.'::text, 'Dine egne mærkater på ryttere, så du kan finde dem på træningssiden.'::text),
  ('00005387-0000-4000-8000-000000000215'::text, 'youth'::text, 10::int, 'active'::text, null::text, 'Youth seasons that count: promotion, relegation and rankings for U23 and junior from season 5.'::text, 'Ungdomssæsoner der tæller: oprykning, nedrykning og ranglister for U23 og junior fra sæson 5.'::text),
  ('00005387-0000-4000-8000-000000000216'::text, 'youth'::text, 20::int, 'active'::text, null::text, 'Prize money in youth races: a smaller pot than the senior races, big enough that a youth win pays, never big enough to carry a club.'::text, 'Præmiepenge i ungdomsløb: en mindre pulje end seniorløbene, stor nok til at en ungdomssejr giver noget, aldrig stor nok til at bære en klub.'::text),
  ('00005387-0000-4000-8000-000000000217'::text, 'youth'::text, 40::int, 'active'::text, null::text, 'Scouts that differ: a better scout finds more, sees more of a rider, and charges less per report.'::text, 'Spejdere der er forskellige: en bedre spejder finder mere, ser mere af en rytter og tager mindre pr. rapport.'::text),
  ('00005387-0000-4000-8000-000000000218'::text, 'youth'::text, 50::int, 'active'::text, null::text, 'Rival riders'' abilities shown as a range, not an exact number, until you have scouted them.'::text, 'Modstanderes evner vises som et interval, ikke et præcist tal, indtil du har spejdet dem.'::text),
  ('00005387-0000-4000-8000-000000000219'::text, 'market'::text, 30::int, 'active'::text, null::text, 'A transfer market you can trust: limits on deals between friends, and every trade in an open log.'::text, 'Et transfermarked du kan stole på: grænser for handler mellem venner, og hver handel i en åben log.'::text),
  ('00005387-0000-4000-8000-000000000220'::text, 'market'::text, 40::int, 'active'::text, null::text, 'More than one wishlist, so you can sort the riders you follow.'::text, 'Mere end én ønskeliste, så du kan sortere de ryttere, du følger.'::text),
  ('00005387-0000-4000-8000-000000000221'::text, 'market'::text, 50::int, 'active'::text, null::text, 'See an injury on another team''s rider, and how long he is out.'::text, 'Se en skade på et andet holds rytter, og hvor længe han er ude.'::text),
  ('00005387-0000-4000-8000-000000000222'::text, 'club'::text, 10::int, 'active'::text, null::text, 'Your club''s look: logo, team colours and rider faces.'::text, 'Din klubs udseende: logo, holdfarver og rytteransigter.'::text),
  ('00005387-0000-4000-8000-000000000223'::text, 'club'::text, 20::int, 'active'::text, null::text, 'Sponsors reworked: a main sponsor plus smaller side sponsors with their own goals.'::text, 'Sponsorer lavet om: en hovedsponsor plus mindre sidesponsorer med egne mål.'::text),
  ('00005387-0000-4000-8000-000000000224'::text, 'club'::text, 30::int, 'active'::text, null::text, 'More facilities: more of your club to build than training and scouting.'::text, 'Flere faciliteter: mere af din klub at bygge ud end træning og scouting.'::text),
  ('00005387-0000-4000-8000-000000000225'::text, 'club'::text, 50::int, 'active'::text, null::text, 'Upkeep reworked: travel and staff costs paid per race day, instead of one big bill at season start.'::text, 'Drift lavet om: rejse- og personaleudgifter betales pr. løbsdag i stedet for én stor regning ved sæsonstart.'::text),
  ('00005387-0000-4000-8000-000000000226'::text, 'club'::text, 70::int, 'active'::text, null::text, 'A new dashboard and inbox: what needs you today comes first, and a message takes seconds to read.'::text, 'Nyt dashboard og ny indbakke: det, der kræver dig i dag, står først, og en besked tager sekunder at læse.'::text),
  ('00005387-0000-4000-8000-000000000227'::text, 'club'::text, 80::int, 'active'::text, null::text, 'A smarter assistant: one message instead of five, and you act straight from the inbox.'::text, 'En klogere assistent: én besked i stedet for fem, og du handler direkte fra indbakken.'::text),
  ('00005387-0000-4000-8000-000000000228'::text, 'club'::text, 120::int, 'active'::text, null::text, 'Rider milestones: goals for one rider you can chase, even when it is not the smart move for the team.'::text, 'Rytter-milepæle: mål for én rytter du kan jagte, også når det ikke er det kloge træk for holdet.'::text),
  ('00005387-0000-4000-8000-000000000301', 'market', 800, 'shipped', '2026-09-14T00:00:00Z', 'All trades in one list: every rider move in the game, newest first.', 'Alle handler i én liste: hvert rytterskifte i spillet, nyeste først.'),
  ('00005387-0000-4000-8000-000000000302', 'club', 800, 'shipped', '2026-09-17T00:00:00Z', 'The beta group: ask to join and try new features before everyone else.', 'Beta-gruppen: bed om at komme med, og prøv nye funktioner før alle andre.'),
  ('00005387-0000-4000-8000-000000000303', 'races', 800, 'shipped', '2026-09-19T00:00:00Z', 'Your assistant tells you when it picked a squad you left empty.', 'Din assistent giver besked, når den har udtaget et hold, du havde ladet stå tomt.')
) as v(id, engine, sort_order, status, shipped_at, title_en, title_da)
where not exists (select 1 from roadmap_items x where x.title_en = v.title_en)
on conflict (id) do nothing;

commit;
